-- public.upgrade_reason(p_world uuid, p_uid uuid)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.upgrade_reason(p_world uuid, p_uid uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare dd deed; v_next int; v_missing text;
begin
  select * into dd from deed where world_id = p_world and founded_by = p_uid;
  if not found then return 'No settlement.'; end if;
  if dd.level >= max_deed_level() then
    return dd.name || ': max level.';
  end if;
  v_next := dd.level + 1;
  select string_agg(w.label, ', ' order by w.label) into v_missing
    from upgrade_wants(p_world, p_uid, v_next) w where not w.met;
  if v_missing is not null then return 'Still needed: ' || v_missing || '.'; end if;
  return null;
end $function$
